package com.himeros.notification;import com.fasterxml.jackson.databind.*;import com.himeros.shared.*;import com.himeros.shared.idempotency.IdempotencyService;import java.util.*;import org.springframework.data.domain.PageRequest;import org.springframework.kafka.annotation.*;import org.springframework.retry.annotation.Backoff;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service public class NotificationService{private final NotificationRepository repo;private final IdempotencyService idempotency;private final ObjectMapper mapper;public NotificationService(NotificationRepository r,IdempotencyService i,ObjectMapper m){repo=r;idempotency=i;mapper=m;}
 @RetryableTopic(attempts="4",backoff=@Backoff(delay=1000,multiplier=2.0),dltTopicSuffix="-dlt")@KafkaListener(topics="himeros.match.events.v1",groupId="notification-dispatcher")public void onMatch(String json){try{JsonNode root=mapper.readTree(json);UUID eventId=UUID.fromString(root.path("eventId").asText());idempotency.executeOnce(eventId,"notification-dispatcher",()->{JsonNode p=root.path("payload");UUID matchId=UUID.fromString(p.path("matchId").asText()),a=UUID.fromString(p.path("userA").asText()),b=UUID.fromString(p.path("userB").asText());repo.save(new Notification(a,"MATCH","Novo match!","Vocês deram match.","{\"matchId\":\""+matchId+"\"}"));repo.save(new Notification(b,"MATCH","Novo match!","Vocês deram match.","{\"matchId\":\""+matchId+"\"}"));});}catch(Exception ex){throw new IllegalStateException("Invalid match event",ex);}}
 @DltHandler public void dlt(String json){/* retained in Kafka DLT for operational replay */}
 @Transactional(readOnly=true)public List<View> list(UUID user,int limit){return repo.list(user,PageRequest.of(0,Math.min(Math.max(limit,1),100))).stream().map(NotificationService::view).toList();}@Transactional public void read(UUID user,UUID id){Notification n=repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Notification not found"));if(!n.user().equals(user))throw new ForbiddenException("Not your notification");n.markRead();}private static View view(Notification n){return new View(n.id(),n.type(),n.title(),n.body(),n.data(),n.read(),n.created());}public record View(UUID id,String type,String title,String body,String dataJson,java.time.Instant readAt,java.time.Instant createdAt){}}
